const err = context.workflow['__TRY_SUPABASE_CALL__']?.error || context.workflow['__CALL_EDGE_FUNCTION__']?.error || {};
const rawMsg = String(err?.response?.data?.error || err?.response?.data?.message || err?.data?.error || err?.data?.message || err?.message || '').toLowerCase();
const status = Number(err?.status || err?.response?.status || 0);

if (status === 401 || status === 403 || rawMsg.includes('unauthorized') || rawMsg.includes('jwt') || rawMsg.includes('token') || rawMsg.includes('non connecté')) {
  return 'Votre session a expiré ou vous n’êtes pas connecté. Veuillez vous reconnecter puis réessayer.';
}
if (status === 409 || rawMsg.includes('attente') || rawMsg.includes('already') || rawMsg.includes('pending') || rawMsg.includes('duplicate') || rawMsg.includes('existe déjà')) {
  return 'Une demande d’abonnement est déjà en attente de traitement pour votre compte.';
}
if (status === 400 || status === 422 || rawMsg.includes('acompte') || rawMsg.includes('invalid') || rawMsg.includes('formule') || rawMsg.includes('champ')) {
  const serverDetail = err?.response?.data?.error || err?.response?.data?.message || err?.data?.error || err?.data?.message;
  return serverDetail ? String(serverDetail) : 'Certaines informations saisies sont invalides. Veuillez vérifier votre formule, vos coordonnées et le montant de l’acompte.';
}
return 'Une erreur technique ou réseau est survenue lors de l’envoi de votre demande d’abonnement. Veuillez réessayer dans quelques instants.';

