// 1. Lire la formule sélectionnée via les cartes et nettoyer les valeurs du formulaire
const formule = String(variables['50073abc-9587-4f5c-8991-2ef82c49fee0'] || 'membre_existant').trim();
const prenom = String(variables['5ab2520b-633a-4106-b637-5070eb030107-value'] || '').trim();
const nom = String(variables['724f529e-cc71-45b6-a000-f5f4dab93f8f-value'] || '').trim();
const emailFacturation = String(variables['dcb9c465-9dba-4ab4-8951-556230d14fd0-value'] || '').trim();
const raisonSociale = String(variables['2958961a-0649-406e-9a73-c7ce07d2414d-value'] || '').trim();
const adresse = String(variables['c7ef7f09-c39a-41f4-b6fc-40b2777c7c90-value'] || '').trim();
const npa = String(variables['bbdafb5e-e860-4fea-892f-09f0b285c8a7-value'] || '').trim();
const localite = String(variables['9c13463a-0f5c-4a7e-a997-291773cb7119-value'] || '').trim();
const pays = String(variables['f405427a-62af-4685-aa21-a3408423e25a-value'] || 'Suisse').trim();
const acompteRaw = String(variables['b374a010-1109-4152-b716-ba3771936607-value'] ?? '').trim().replace(',', '.');
const acompte = Number(acompteRaw);
const conditionsAcceptees = Boolean(variables['eaf69eed-0d55-4f2c-961e-10949b99db32-value']);

// 2. Vérifier le choix de la formule
const formulesValides = ['membre_existant', 'acces_plateforme', 'adhesion_hrvalais'];
if (!formulesValides.includes(formule)) {
  return { valid: false, errorMessage: 'Veuillez sélectionner votre formule d’abonnement.' };
}

// 3. Vérifier les coordonnées de facturation obligatoires
if (!prenom || !nom || !emailFacturation || !adresse || !npa || !localite || !pays) {
  return { valid: false, errorMessage: 'Veuillez compléter tous les champs obligatoires de vos coordonnées de facturation.' };
}
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(emailFacturation)) {
  return { valid: false, errorMessage: 'Veuillez saisir une adresse e-mail de facturation valide.' };
}

// 4. Vérifier le montant de l'acompte IA (> 0, <= 10000, 2 décimales maximum)
const twoDecimalsRegex = /^\d+(\.\d{1,2})?$/;
if (!acompteRaw || !Number.isFinite(acompte) || acompte <= 0 || acompte > 10000 || !twoDecimalsRegex.test(acompteRaw)) {
  return { valid: false, errorMessage: 'Veuillez indiquer un acompte initial de consommation IA valide (supérieur à CHF 0.–, inférieur ou égal à CHF 10\'000.–, avec 2 décimales maximum).' };
}

// 5. Vérifier l'acceptation des conditions
if (!conditionsAcceptees) {
  return { valid: false, errorMessage: 'Veuillez accepter les conditions applicables avant d’envoyer votre demande.' };
}

// 6. Récupérer le jeton d'accès (access_token) de l'utilisateur connecté via Supabase
const supabaseClient = wwLib.wwPlugins?.supabaseAuth?.publicInstance || wwLib.wwPlugins?.supabase?.instance;
let accessToken = '';
if (supabaseClient?.auth?.getSession) {
  const { data } = await supabaseClient.auth.getSession();
  accessToken = data?.session?.access_token || '';
}
if (!accessToken) {
  return { valid: false, errorMessage: 'Votre session utilisateur est introuvable ou a expiré. Veuillez vous reconnecter avant d’envoyer votre demande d’abonnement.' };
}

return {
  valid: true,
  token: accessToken,
  payload: {
    formule,
    acompte_chf: Number(acompte.toFixed(2)),
    prenom,
    nom,
    email_facturation: emailFacturation,
    raison_sociale: raisonSociale,
    adresse,
    npa,
    localite
  }
};

